import{_ as a,o,c as e,a2 as l}from"./chunks/framework.C4u7U0Dw.js";const q=JSON.parse('{"title":"第 4 课 第一次试一下：5 分钟跑通一件事","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第4课 第一次试一下：5分钟跑通一件事.md","filePath":"easy/第4课 第一次试一下：5分钟跑通一件事.md"}'),r={name:"easy/第4课 第一次试一下：5分钟跑通一件事.md"};function i(s,t,n,u,d,p){return o(),e("div",null,[...t[0]||(t[0]=[l(`<h1 id="第-4-课-第一次试一下-5-分钟跑通一件事" tabindex="-1">第 4 课 第一次试一下：5 分钟跑通一件事 <a class="header-anchor" href="#第-4-课-第一次试一下-5-分钟跑通一件事" aria-label="Permalink to &quot;第 4 课 第一次试一下：5 分钟跑通一件事&quot;">​</a></h1><h2 id="课前准备-30-秒" tabindex="-1">课前准备（30 秒） <a class="header-anchor" href="#课前准备-30-秒" aria-label="Permalink to &quot;课前准备（30 秒）&quot;">​</a></h2><p>找一件<strong>真的要做</strong>的小事，别用练习题。标准是：</p><ul><li>你最近真的需要它；</li><li>10 分钟内能做完；</li><li>结果能看出来（比如：一页纸、一个文件、一个答案）。</li></ul><p><strong>找不到？</strong> 那就用这个现成的：<em>&quot;帮我写一份本周工作计划，3 条就行，中文。&quot;</em></p><h2 id="第-1-步-把话按-点菜公式-说出去-1-分钟" tabindex="-1">第 1 步：把话按&quot;点菜公式&quot;说出去（1 分钟） <a class="header-anchor" href="#第-1-步-把话按-点菜公式-说出去-1-分钟" aria-label="Permalink to &quot;第 1 步：把话按&quot;点菜公式&quot;说出去（1 分钟）&quot;">​</a></h2><p>复制下面，把 <code>{ }</code> 换掉，发给我：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我想要：{你的小事}</span></span>
<span class="line"><span>资料在：{有就写位置，没有就写&quot;没有&quot;}</span></span>
<span class="line"><span>要求是：{中文/简短/格式……}</span></span>
<span class="line"><span>咋算好：{你觉得怎么算好}</span></span></code></pre></div><p><strong>发完之后，别急着走，看我的反应。</strong></p><h2 id="第-2-步-听我复述-对齐一次-1-分钟" tabindex="-1">第 2 步：听我复述，对齐一次（1 分钟） <a class="header-anchor" href="#第-2-步-听我复述-对齐一次-1-分钟" aria-label="Permalink to &quot;第 2 步：听我复述，对齐一次（1 分钟）&quot;">​</a></h2><p>我大概率会说：&quot;我理解你要做的是……对吗？&quot;</p><ul><li>✅ 对 → 说&quot;对，开始&quot;；</li><li>❌ 不对 → 直接纠正：&quot;不是要 A，是要 B&quot;。</li></ul><p><strong>这一步最重要。</strong> 对齐错了，后面全白干；对齐对了，后面基本稳。</p><h2 id="第-3-步-看我干活-1-2-分钟" tabindex="-1">第 3 步：看我干活（1～2 分钟） <a class="header-anchor" href="#第-3-步-看我干活-1-2-分钟" aria-label="Permalink to &quot;第 3 步：看我干活（1～2 分钟）&quot;">​</a></h2><p>我会一步步做：读文件、列大纲、写内容……</p><p>你可以随时插话：</p><ul><li>&quot;先别写，先给我看大纲&quot;（更好）；</li><li>&quot;停，这里不是这样&quot;（没问题）；</li><li>&quot;换个风格&quot;（随时说）。</li></ul><h2 id="第-4-步-检查成品-1-分钟-——别跳过" tabindex="-1">第 4 步：检查成品（1 分钟）——别跳过！ <a class="header-anchor" href="#第-4-步-检查成品-1-分钟-——别跳过" aria-label="Permalink to &quot;第 4 步：检查成品（1 分钟）——别跳过！&quot;">​</a></h2><p>拿到结果，花 1 分钟检查，按你第 1 步写的&quot;咋算好&quot;逐条看：</p><ul><li>数字对吗？格式对吗？有没有漏的？</li><li>不对 → 说&quot;这里改一下：……&quot;（很正常！）；</li><li>对 → 说声&quot;可以&quot;，收工。</li></ul><h2 id="第-5-步-存个小本本-30-秒-可选但推荐" tabindex="-1">第 5 步：存个小本本（30 秒，可选但推荐） <a class="header-anchor" href="#第-5-步-存个小本本-30-秒-可选但推荐" aria-label="Permalink to &quot;第 5 步：存个小本本（30 秒，可选但推荐）&quot;">​</a></h2><p>跟它说一句：</p><blockquote><p>&quot;记住：我喜欢 {简洁/中文/表格/……} 的风格。&quot;</p></blockquote><p>下次它就更懂你了。</p><h2 id="如果卡住了怎么办" tabindex="-1">如果卡住了怎么办？ <a class="header-anchor" href="#如果卡住了怎么办" aria-label="Permalink to &quot;如果卡住了怎么办？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>怎么办</th></tr></thead><tbody><tr><td>它没听懂</td><td>重新说一遍，换个说法，别忍着</td></tr><tr><td>它做错了</td><td>&quot;这里不对，应该是……&quot; 直接说</td></tr><tr><td>你也不知道想要啥</td><td>让它&quot;先给我 2 个方案看看&quot;</td></tr><tr><td>完全乱了</td><td>&quot;从头来，我们重新对齐一次&quot;</td></tr></tbody></table><h2 id="课后作业" tabindex="-1">课后作业 <a class="header-anchor" href="#课后作业" aria-label="Permalink to &quot;课后作业&quot;">​</a></h2><p>现在就去试。<strong>跑通一件小事，比读十节课都值钱。</strong> 跑通了，你就正式&quot;会用 AI 干活&quot;了。</p><p>👉 跑通之后，看看 [第 5 课：问得最多的 10 个问题](第5课 问得最多的10个问题.md)，把坑提前避掉。</p>`,29)])])}const c=a(r,[["render",i]]);export{q as __pageData,c as default};
